package com.ecobridge.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="community_members",uniqueConstraints=@UniqueConstraint(columnNames={"community_id","user_id"})) public class CommunityMember {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="community_id",nullable=false) private Long communityId; @Column(name="user_id",nullable=false) private Long userId; @Column(nullable=false,length=30) private String role="MEMBER"; @Column(name="membership_status",nullable=false,length=30) private String membershipStatus="ACTIVE"; @Column(name="joined_at",nullable=false) private Instant joinedAt=Instant.now(); public Long getId(){return id;} public Long getCommunityId(){return communityId;} public void setCommunityId(Long v){communityId=v;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getRole(){return role;} public void setRole(String v){role=v;} }
